//! The benchmark's fixture host (bench profile only): the fixture pages over HTTPS under one name, with a certificate
//! made at start. It writes the certificate's SPKI SHA-256 (base64) to [`SPKI_FILE`], so a bench session's Chromium
//! can accept exactly this certificate and nothing else.
//!
//! `/big?size=N` is a download of N generated bytes (byte i is [`big_byte`]`(i)`), served as fast as the connection
//! takes it, for the large-download tests. With `&cut=M&id=X`, the first request of `X` breaks its connection after M
//! bytes, as a network that drops does, and every later one serves other bytes (each [`big_byte`] inverted), as a
//! resource that changed does: a download that Chromium starts again must never reach the person mixed. Each request
//! of an id is logged (`big <id>: request <n>`), so a test can tell that Chromium did start it again.

use std::collections::HashMap;
use std::sync::{Arc, Mutex};

use base64::Engine;
use rcgen::PublicKeyData;
use sha2::{Digest, Sha256};

const NAME: &str = "fixture.bench";
const DIR: &str = "/srv/fixtures";
const LISTEN: std::net::SocketAddr =
    std::net::SocketAddr::new(std::net::IpAddr::V4(std::net::Ipv4Addr::UNSPECIFIED), 443);
const SPKI_FILE: &str = "/run/bench/spki";

#[tokio::main]
async fn main() -> Result<(), String> {
    let certified = rcgen::generate_simple_self_signed(vec![NAME.to_owned()]).map_err(|e| e.to_string())?;
    let spki = Sha256::digest(certified.signing_key.subject_public_key_info());
    let spki = base64::engine::general_purpose::STANDARD.encode(spki);
    std::fs::write(SPKI_FILE, &spki).map_err(|e| e.to_string())?;
    let cert = certified.cert.der().clone();
    let key = rustls::pki_types::PrivateKeyDer::Pkcs8(certified.signing_key.serialize_der().into());
    let provider = Arc::new(rustls::crypto::ring::default_provider());
    let mut config = rustls::ServerConfig::builder_with_provider(provider)
        .with_safe_default_protocol_versions()
        .map_err(|e| e.to_string())?
        .with_no_client_auth()
        .with_single_cert(vec![cert], key)
        .map_err(|e| e.to_string())?;
    config.alpn_protocols = vec![b"http/1.1".to_vec()];
    println!("fixture host {NAME} on {LISTEN}, SPKI sha256/{spki}");
    let app = axum::Router::new()
        .route("/big", axum::routing::get(big))
        .route("/accept-language", axum::routing::get(accept_language))
        .fallback_service(tower_http::services::ServeDir::new(DIR));
    axum_server::bind_rustls(LISTEN, axum_server::tls_rustls::RustlsConfig::from_config(Arc::new(config)))
        .serve(app.into_make_service())
        .await
        .map_err(|e| e.to_string())
}

/// The request's Accept-Language header, which the stealth probe compares with navigator.languages.
async fn accept_language(headers: axum::http::HeaderMap) -> String {
    headers.get("accept-language").and_then(|v| v.to_str().ok()).unwrap_or_default().to_owned()
}

/// Byte `i` of every `/big` download.
fn big_byte(i: u64) -> u8 {
    (i.wrapping_mul(7) ^ (i >> 8) ^ (i >> 24)) as u8
}

#[derive(serde::Deserialize)]
struct Big {
    size: u64,
    #[serde(default)]
    cut: Option<u64>,
    #[serde(default)]
    id: Option<String>,
}

/// How often each cut download was asked for.
static CUT: Mutex<Option<HashMap<String, u32>>> = Mutex::new(None);

async fn big(axum::extract::Query(Big { size, cut, id }): axum::extract::Query<Big>) -> axum::response::Response {
    const PIECE: u64 = 1 << 20;
    let asked = id.map(|id| {
        let mut cut = CUT.lock().unwrap();
        let count = cut.get_or_insert_default().entry(id.clone()).or_default();
        *count += 1;
        println!("big {id}: request {count}");
        *count
    });
    let first = asked == Some(1);
    let (cut, changed) = match cut {
        Some(cut) if first => (Some(cut), false),
        Some(_) => (None, true),
        None => (None, false),
    };
    let pieces = futures_util::stream::unfold(0u64, move |at| async move {
        if cut.is_some_and(|cut| at >= cut) {
            return Some((Err(std::io::Error::other("the connection drops")), u64::MAX));
        }
        if at >= size {
            return None;
        }
        let end = (at + PIECE).min(size).min(cut.unwrap_or(u64::MAX));
        let bytes: Vec<u8> = (at..end).map(|i| if changed { !big_byte(i) } else { big_byte(i) }).collect();
        Some((Ok::<_, std::io::Error>(axum::body::Bytes::from(bytes)), end))
    });
    axum::response::Response::builder()
        .header("content-type", "application/octet-stream")
        .header("content-length", size)
        .header("content-disposition", "attachment; filename=\"big.bin\"")
        .body(axum::body::Body::from_stream(pieces))
        .unwrap_or_default()
}
